$(function(){var n=$("#profile-image");n.click(function(){var t=$(document).width(),i=$(document).height(),r=75+Math.random()*(t-150),u=75+Math.random()*(i-150);n.css({top:u+"px",left:r+"px",position:"fixed"});gtag("event","profile_click",{event_category:"Profile Image Click"})});$("#main-menu-button").click(function(){gtag("event","link",{event_category:"Main Menu Button",href:$(this).attr("href")})})});